// Read returns the file's contents. A missing file is reported unwrapped so
// callers can classify it with os.IsNotExist, which is how every agent's
// install path decides between "merge into existing" and "write fresh".
func (f *HookConfigFile) Read() ([]byte, error) {
	return osroot.ReadFileNoFollow(f.root, f.name) //nolint:wrapcheck // see doc comment
}
=== ReadFileNoFollow (what Read presumably uses) ===
// ReadFileNoFollow reads name while refusing a symbolic link in any component.
// os.Root already prevents a link from escaping root, but follows links whose
// targets remain inside it. Entire-owned trees require the stronger property:
// every component must identify the object stored at that name.
func ReadFileNoFollow(root *os.Root, name string) ([]byte, error) {
	f, err := OpenNoFollow(root, name)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

